import 'dart:math';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// One-shot game sound effects (assets/audio/, generated by scripts/gen_sfx.py).
///
/// Sound must NEVER break gameplay: every play call is fire-and-forget and
/// swallows platform errors (e.g. missing audio focus, or running in a test
/// environment with no plugin). Widget tests get [SilentGameSfx] via DI.
abstract class GameSfx {
  /// SharedPreferences key for the player's mute choice.
  static const String mutedPrefsKey = 'sfx_muted';

  /// App-wide mute switch (the speaker toggle on the task screen). Static so
  /// every implementation honours it, including the const [SilentGameSfx]
  /// that widget tests register.
  static final ValueNotifier<bool> muted = ValueNotifier<bool>(false);

  static bool _muteLoaded = false;

  /// Reads the saved mute choice once. Safe to call repeatedly and safe in
  /// tests with no prefs plugin (it just stays unmuted).
  static Future<void> loadMutePreference() async {
    if (_muteLoaded) return;
    _muteLoaded = true;
    try {
      final prefs = await SharedPreferences.getInstance();
      muted.value = prefs.getBool(mutedPrefsKey) ?? false;
    } catch (e) {
      debugPrint('GameSfx: could not read mute preference: $e');
    }
  }

  /// Flips the mute switch now and saves it for next time.
  static Future<void> setMuted(bool value) async {
    muted.value = value;
    _muteLoaded = true;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool(mutedPrefsKey, value);
    } catch (e) {
      debugPrint('GameSfx: could not save mute preference: $e');
    }
  }

  /// Test hook: forget the loaded preference and unmute.
  @visibleForTesting
  static void resetMuteForTest() {
    _muteLoaded = false;
    muted.value = false;
  }

  /// Unlock audio from inside a user gesture (a tap). Browsers only let a
  /// page make sound after the player has touched it, and iOS Safari unlocks
  /// each audio element separately, so the task screen calls this from the
  /// Start / Film it / Snap it taps to make the later countdown ticks (which
  /// fire from a timer, not a tap) audible. A no-op off the web.
  void prime();

  /// Balloon pop. [pitch] lets callers randomize slightly (~0.9–1.15) so a
  /// rapid streak of pops doesn't sound robotic.
  void pop({double pitch = 1.0});

  /// Bomb explosion.
  void boom();

  /// Countdown tick (pre-roll digits + last seconds of the round).
  void tick();

  /// Round-start "GO!".
  void go();

  /// Round-over jingle.
  void fanfare();

  /// A balloon escaping upward.
  void whoosh();

  /// A RIVAL popped a balloon (shared race) — fiery crackle.
  void sizzle();
}

class AudioGameSfx implements GameSfx {
  // A small pool so overlapping pops don't cut each other off. lowLatency mode
  // keeps the sample resident for tap-synced playback.
  final List<AudioPlayer> _pool;
  int _next = 0;
  final Random _random = Random();

  // The countdown tick gets its own player. Ticks fire from a timer, not a
  // tap, so on the web they need an audio element that was already unlocked
  // by a gesture ([prime]) and that keeps the same source (audioplayers_web
  // rebuilds the element whenever the source changes).
  final AudioPlayer _tickPlayer;
  bool _primed = false;

  AudioGameSfx({int poolSize = 4})
      : _pool = List.generate(poolSize, (_) => _newPlayer()),
        _tickPlayer = _newPlayer() {
    GameSfx.loadMutePreference();
  }

  static AudioPlayer _newPlayer() {
    final p = AudioPlayer();
    p.setPlayerMode(PlayerMode.lowLatency);
    p.setReleaseMode(ReleaseMode.stop);
    return p;
  }

  void _play(String file, {double rate = 1.0, AudioPlayer? on}) {
    if (GameSfx.muted.value) return;
    final AudioPlayer player;
    if (on != null) {
      player = on;
    } else {
      player = _pool[_next];
      _next = (_next + 1) % _pool.length;
    }
    // Fire and forget; a lost sound is better than a frame hitch or a crash.
    Future(() async {
      try {
        await player.stop();
        await player.setVolume(1.0);
        await player.setPlaybackRate(rate);
        await player.play(AssetSource('audio/$file'));
      } catch (e) {
        debugPrint('GameSfx: could not play $file: $e');
      }
    });
  }

  @override
  void prime() {
    if (!kIsWeb || _primed) return;
    _primed = true;
    // Play the tick silently on its dedicated player while we are still
    // inside the tap's user activation. (iOS ignores volume on media
    // elements, so there it is an audible click on the tap, which is fine.)
    Future(() async {
      try {
        await _tickPlayer.play(AssetSource('audio/tick.wav'), volume: 0);
      } catch (e) {
        _primed = false;
        debugPrint('GameSfx: could not unlock audio: $e');
      }
    });
  }

  @override
  void pop({double pitch = 1.0}) {
    // Small extra randomization on top of whatever the caller asked for.
    final jitter = 0.97 + _random.nextDouble() * 0.06;
    _play('pop.wav', rate: (pitch * jitter).clamp(0.5, 2.0));
  }

  @override
  void boom() => _play('boom.wav');

  @override
  void tick() => _play('tick.wav', on: _tickPlayer);

  @override
  void go() => _play('go.wav');

  @override
  void fanfare() => _play('fanfare.wav');

  @override
  void whoosh() => _play('whoosh.wav');

  @override
  void sizzle() => _play('sizzle.wav');
}

/// No-op implementation for tests (and any platform without audio).
class SilentGameSfx implements GameSfx {
  const SilentGameSfx();

  @override
  void prime() {}

  @override
  void pop({double pitch = 1.0}) {}
  @override
  void boom() {}
  @override
  void tick() {}
  @override
  void go() {}
  @override
  void fanfare() {}
  @override
  void whoosh() {}
  @override
  void sizzle() {}
}
